actions.script:
const projectId = ec.context.get('projectTabId') || null
const access = projectId ? ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: projectId, need: 'none'}).call() || {} : {}
if (!access.canView) { ec.web.sendJsonResponse({project: {workEffortId: workEffortId || null, workEffortName: '', canUpdate: false, notAvailable: true}}); return }
const out = ec.service.sync().name('ironstone.commons.CalendarServices.get#CalendarSetup').call() || {}
ec.message.clearErrors()
ec.web.sendJsonResponse({calendarList: out.calendarList || [], defaultCalendarId: out.defaultCalendarId || null, defaults: out.defaults || {},
    timeZone: out.timeZone, todayText: out.todayText, nowText: out.nowText, me: out.me, roomOptions: out.roomOptions || [], failedSources: out.failedSources || [],
    project: {workEffortId: projectId, workEffortName: access.project?.workEffortName || projectId, canUpdate: !!access.canUpdate}})

const out = ec.service.sync().name('ironstone.projects.PlanningServices.get#ProjectCalendarEvents').parameters({rootWorkEffortId: ec.context.get('projectTabId') || workEffortId || '',
    start: start || '', end: end || ''}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {eventList: out.eventList || [], failedSources: out.failedSources || [], skippedCalendarIdList: []})

const out = ec.service.sync().name('ironstone.commons.CalendarServices.get#EventSummary').parameters({workEffortId: eventWorkEffortId || ec.context.get('workEffortId') || '',
    instanceStart: instanceStart || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() || !out.visible ? {visible: false} : {visible: true, event: out.event})

const projectId = ec.context.get('projectTabId') || ''
ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: projectId, need: 'update'}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const out = ec.service.sync().name('ironstone.commons.CalendarServices.create#QuickEvent').parameters({workEffortName: workEffortName || '',
    start: start || '', end: end || null, allDay: allDay || 'N', calendarId: calendarId || null, facilityId: facilityId || null,
    attendeePartyIds: attendeePartyIds || null, repeat: repeat || null, reminderMinutes: reminderMinutes ?? null, location: location || null,
    description: description || null}).call() || {}
if (!ec.message.hasError()) ec.service.sync().name('mantle.work.WorkEffortServices.link#WorkEffortRecord').parameters({workEffortId: out.workEffortId,
    recordEntityName: 'mantle.work.effort.WorkEffort', recordId: projectId}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : Object.assign({workEffortId: out.workEffortId, url: out.url, messageInfos: [{type: 'success',
    message: out.message, link: out.url, linkText: ec.l10n.localize('Open')}].concat((out.warningList || []).map((text) => ({type: 'warning', message: text})))},
    andOpen === 'Y' && out.url ? {screenUrl: out.url} : {}))

const id = ec.context.get('eventWorkEffortId') || ''
const record = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).one()
if (record != null && record.workEffortTypeEnumId !== 'WetEvent') {
    const out = ec.service.sync().name('ironstone.projects.PlanningServices.move#ProjectCalendarItem').parameters({workEffortId: id, start: start || '', end: end || null}).call() || {}
    ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: out.message}]})
    return
}
ec.service.sync().name('ironstone.commons.CalendarServices.get#EventAccessInfo').parameters({workEffortId: id, need: 'edit'}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const theScope = scope || 'all'
const out = ec.service.sync().name('mantle.work.EventServices.update#EventOccurrence').parameters({workEffortId: id,
    instanceStart: instanceStart || null, scope: theScope, start: start || null, end: end || null, allDay: allDay || null,
    notify: notify || 'N', eventUrl: '/qapps/Commons/Calendar/EventDetail?workEffortId=' + encodeURIComponent(id),
    allowConflicts: allowConflicts === 'Y' || allowConflicts === 'true'}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({bookingClash: / is booked then: /.test(ec.message.getErrorsString())}); return }
ec.web.sendJsonResponse({targetWorkEffortId: out.targetWorkEffortId, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.commons.CalendarServices.respond#Invitation').parameters({workEffortId: ec.context.get('eventWorkEffortId') || '',
    response: response || '', message: message || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {statusId: out.statusId, messageInfos: [{type: 'success', message: out.resultMessage}]})
